class FastNTriplesParserOptimizationTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void wordScansRespectEveryAlignmentAndTail() {
		byte[] markers = { '\n', '\r', '"', '\\', '>', (byte) 0x80, (byte) 0xff, 0, 'a' };
		for (int offset = 0; offset < 16; offset++) {
			for (int length = 0; length < 40; length++) {
				for (int position = 0; position <= length; position++) {
					for (byte marker : markers) {
						byte[] bytes = new byte[offset + length + 16];
						Arrays.fill(bytes, (byte) '\n');
						Arrays.fill(bytes, offset, offset + length, (byte) 'a');
						if (position < length) {
							bytes[offset + position] = marker;
							// Exercise the borrow into the next byte in the zero-byte detector.
							if (position + 1 < length) {
								bytes[offset + position + 1] = (byte) (marker ^ 1);
							}
						}
						assertScansMatchScalar(bytes, offset, offset + length);
					}
				}
			}
		}
	}

	@Test
	void wordScansMatchScalarOnArbitraryBytesAndSlices() {
		Random random = new Random(0x52df4aL);
		for (int iteration = 0; iteration < 10_000; iteration++) {
			int offset = random.nextInt(16);
			int length = random.nextInt(192);
			byte[] bytes = new byte[offset + length + random.nextInt(16)];
			random.nextBytes(bytes);
			assertScansMatchScalar(bytes, offset, offset + length);
		}
	}

	@Test
	void wordScansHandleEveryByteValueAtEveryWordPosition() {
		for (int offset = 0; offset < 16; offset++) {
			for (int position = 0; position < 24; position++) {
				for (int value = 0; value < 256; value++) {
					byte[] bytes = new byte[offset + 32];
					Arrays.fill(bytes, (byte) 'a');
					bytes[offset + position] = (byte) value;
					bytes[offset + position + 1] = (byte) (value ^ 1);
					assertScansMatchScalar(bytes, offset, bytes.length);
				}
			}
		}
	}

	@Test
	void iriWordScanPreservesTheFirstLexicalErrorAndColumn() {
		FastNTriplesParser parser = parser();
		byte[] forbidden = { 0, 1, '\t', ' ', '<', '"', '{', '}', '|', '^', '`' };
		for (int offset = 0; offset < 16; offset++) {
			for (int prefix = 0; prefix < 16; prefix++) {
				for (byte value : forbidden) {
					String start = "<urn:" + "a".repeat(prefix);
					// Include a later invalid escape: the earlier forbidden raw byte must still win.
					byte[] document = (start + (char) value + "tail\\uD800> <urn:p> <urn:o> .").getBytes(UTF_8);
					assertIriError(parser, document, offset, "Invalid character in IRI", start.length() + 1L);
					byte[] unescaped = (start + (char) value + "tail> <urn:p> <urn:o> .").getBytes(UTF_8);
					assertIriError(parser, unescaped, offset, "Invalid character in IRI", start.length() + 1L);
				}
			}
		}
	}

	@Test
	void iriWordScanPreservesStrictValidationDiagnostics() {
		FastNTriplesParser parser = parser();
		for (String iri : List.of("relative", "1scheme:value", "http://exa%GGmple.org/x", "http://u@@host/x",
				"http://[not-ipv6]/x", "urn:too#many#fragments", "urn:path\ue000")) {
			byte[] token = ("<" + iri + ">").getBytes(UTF_8);
			byte[] document = ("<" + iri + "> <urn:p> <urn:o> .").getBytes(UTF_8);
			for (int offset = 0; offset < 16; offset++) {
				assertIriError(parser, document, offset, "Invalid absolute IRI", token.length);
			}
		}
		for (int offset = 0; offset < 16; offset++) {
			assertIriError(parser, "<urn:unterminated".getBytes(UTF_8), offset, "Unterminated IRI", 1);
			assertIriError(parser, "<urn:bad\\uD800> <urn:p> <urn:o> .".getBytes(UTF_8), offset,
					"Invalid Unicode escape sequence", 9);
		}
	}

	@Test
	void iriWordScanRejectsMalformedUtf8AtEveryWordPosition() {
		FastNTriplesParser parser = parser();
		List<byte[]> invalidUtf8 = List.of(new byte[] { (byte) 0x80 },
				new byte[] { (byte) 0xc0, (byte) 0xaf }, new byte[] { (byte) 0xc2, 'a' },
				new byte[] { (byte) 0xed, (byte) 0xa0, (byte) 0x80 }, new byte[] { (byte) 0xe2, (byte) 0x82 },
				new byte[] { (byte) 0xf4, (byte) 0x90, (byte) 0x80, (byte) 0x80 });
		for (int offset = 0; offset < 16; offset++) {
			for (int prefix = 0; prefix < 16; prefix++) {
				byte[] start = ("<urn:" + "a".repeat(prefix)).getBytes(UTF_8);
				byte[] end = "> <urn:p> <urn:o> .".getBytes(UTF_8);
				for (byte[] invalid : invalidUtf8) {
					byte[] document = new byte[start.length + invalid.length + end.length];
					System.arraycopy(start, 0, document, 0, start.length);
					System.arraycopy(invalid, 0, document, start.length, invalid.length);
					System.arraycopy(end, 0, document, start.length + invalid.length, end.length);
					assertIriError(parser, document, offset, "Invalid absolute IRI",
							start.length + invalid.length + 1L);
				}
			}
		}
	}

	@Test
	void literalFastPathPreservesEscapesAndUnicodeAtWordBoundaries() throws IOException {
		FastNTriplesParser parser = parser();
		for (int offset = 0; offset < 16; offset++) {
			for (int prefix = 0; prefix < 24; prefix++) {
				String ascii = "a".repeat(prefix);
				for (String[] suffix : List.of(new String[] { "plain", "plain" },
						new String[] { "\\nend", "\nend" }, new String[] { "\\\"end", "\"end" },
						new String[] { "\\\\end", "\\end" }, new String[] { "é😀end", "é😀end" },
						new String[] { "é\\U0001F600end", "é😀end" })) {
					String input = "<urn:s> <urn:p> \"" + ascii + suffix[0] + "\"@EN-us <urn:g> .\n";
					byte[] document = input.getBytes(UTF_8);
					byte[] bytes = new byte[offset + document.length + 16];
					Arrays.fill(bytes, (byte) '"');
					System.arraycopy(document, 0, bytes, offset, document.length);
					List<byte[][]> statements = new ArrayList<>();
					parser.parseBlock(bytes, offset, document.length, 1, sink(statements));
					assertEquals(1, statements.size());
					assertArrayEquals(CanonicalTermCodec.encode(VF.createLiteral(ascii + suffix[1], "en-us")),
							statements.get(0)[2]);
				}
			}
		}
	}

	@Test
	void retainedTermsSurviveInputOverwriteAndParserReuse() throws IOException {
		FastNTriplesParser parser = parser();
		String input = "<urn:s> <urn:predicat\\u0065> \"a\\nb\"^^<urn:datatyp\\u0065> <urn:graph> .\n";
		byte[] bytes = input.getBytes(UTF_8);
		List<byte[][]> statements = new ArrayList<>();
		parser.parseBlock(bytes, 0, bytes.length, 1, sink(statements));
		byte[][] retained = statements.get(0);
		byte[][] expected = Arrays.stream(retained).map(byte[]::clone).toArray(byte[][]::new);
		Arrays.fill(bytes, (byte) '!');
		for (int i = 0; i < 80; i++) {
			String next = "<urn:subject:" + i + "> <urn:predicate:" + i + "> \"new\\tvalue\"^^<urn:type:" + i
					+ "> <urn:graph:" + i + "> .\n";
			parser.parse(new ByteArrayInputStream(next.getBytes(UTF_8)), sink(statements));
		}
		parser.parse(new ByteArrayInputStream(input.getBytes(UTF_8)), sink(statements));
		for (int role = 0; role < 4; role++) {
			assertArrayEquals(expected[role], retained[role]);
			assertArrayEquals(expected[role], statements.get(statements.size() - 1)[role]);
		}
		assertArrayEquals(CanonicalTermCodec.encode(VF.createLiteral("a\nb", VF.createIRI("urn:datatype"))),
				retained[2]);
	}

	@Test
	void sameFingerprintAndEvictionNeverChangeCanonicalTerms() throws IOException {
		FastNTriplesParser parser = parser();
		for (int pass = 0; pass < 3; pass++) {
			for (int index = 0; index < 80; index++) {
				// Same length, first eight bytes and last eight bytes deliberately collide in the vocabulary cache.
				String iri = "urn:cache:" + String.format(java.util.Locale.ROOT, "%03d", index) + ":fixed-tail";
				List<byte[][]> statements = parse(parser,
						"<urn:s> <" + iri + "> \"value\"^^<" + iri + "> <" + iri + "> .\n");
				assertArrayEquals(CanonicalTermCodec.encode(VF.createIRI(iri)), statements.get(0)[1]);
				assertArrayEquals(CanonicalTermCodec.encode(VF.createLiteral("value", VF.createIRI(iri))),
						statements.get(0)[2]);
				assertArrayEquals(CanonicalTermCodec.encode(VF.createIRI(iri)), statements.get(0)[3]);
			}
		}
	}

	@Test
	void cachedTokensCannotHideInvalidOrTruncatedIris() throws IOException {
		String valid = "http://example.org/aaaaaaaaa/last-end";
		String invalid = "http://example.org/aaaa%GGaa/last-end";
		for (int role = 0; role < 3; role++) {
			FastNTriplesParser parser = parser();
			String warmed = quadWithIri(role, valid);
			parse(parser, warmed);
			parse(parser, warmed);
			String malformed = quadWithIri(role, invalid);
			assertThrows(RDFParseException.class, () -> parse(parser, malformed));
			String truncated = warmed.substring(0, warmed.indexOf(valid) + valid.length());
			assertThrows(RDFParseException.class, () -> parse(parser, truncated));
			assertEquals(1, parse(parser, warmed).size());
		}
	}

	@Test
	void longVocabularyTokensRemainIndependentOfInput() throws IOException {
		String iri = "urn:" + "long".repeat(512);
		FastNTriplesParser parser = parser();
		byte[] input = quadWithIri(0, iri).getBytes(UTF_8);
		List<byte[][]> statements = new ArrayList<>();
		parser.parseBlock(input, 0, input.length, 1, sink(statements));
		Arrays.fill(input, (byte) 'x');
		assertArrayEquals(CanonicalTermCodec.encode(VF.createIRI(iri)), statements.get(0)[1]);
		assertEquals(1, parse(parser, quadWithIri(0, iri)).size());
	}

	@Test
	void languageSlicesFoldIntoCanonicalBytesWithoutChangingInput() {
		byte[] label = "_label_".getBytes(UTF_8);
		byte[] language = "_EN-lAtN-us_".getBytes(UTF_8);
		byte[] before = language.clone();
		for (int direction = 0; direction <= 2; direction++) {
			Literal literal = direction == 0 ? VF.createLiteral("label", "en-latn-us")
					: VF.createLiteral("label", "en-latn-us",
							direction == 1 ? Literal.BaseDirection.LTR : Literal.BaseDirection.RTL);
			byte[] datatype = literal.getDatatype().stringValue().getBytes(UTF_8);
			assertArrayEquals(CanonicalTermCodec.encode(literal),
					CanonicalTermCodec.encodeLiteral(label, 1, label.length - 2, datatype, 0, datatype.length,
							language, 1, language.length - 2, direction));
		}
		assertArrayEquals(before, language);
	}

	private static String quadWithIri(int role, String iri) {
		return switch (role) {
		case 0 -> "<urn:s> <" + iri + "> <urn:o> <urn:g> .\n";
		case 1 -> "<urn:s> <urn:p> <urn:o> <" + iri + "> .\n";
		default -> "<urn:s> <urn:p> \"value\"^^<" + iri + "> <urn:g> .\n";
		};
	}

	private static FastNTriplesParser parser() {
		return new FastNTriplesParser(RDFFormat.NQUADS, () -> false);
	}

	private static List<byte[][]> parse(FastNTriplesParser parser, String input) throws IOException {
		byte[] bytes = input.getBytes(UTF_8);
		List<byte[][]> statements = new ArrayList<>();
		parser.parseBlock(bytes, 0, bytes.length, 1, sink(statements));
		return statements;
	}

	private static FastNTriplesParser.StatementSink sink(List<byte[][]> statements) {
		return (subject, predicate, object, graph) -> statements
				.add(new byte[][] { subject, predicate, object, graph });
	}

	private static void assertIriError(FastNTriplesParser parser, byte[] document, int offset, String message,
			long column) {
		byte[] bytes = new byte[offset + document.length + 16];
		Arrays.fill(bytes, (byte) '>');
		System.arraycopy(document, 0, bytes, offset, document.length);
		RDFParseException failure = assertThrows(RDFParseException.class,
				() -> parser.parseBlock(bytes, offset, document.length, 71, (s, p, o, g) -> {
				}));
		assertEquals(71, failure.getLineNumber());
		assertEquals(column, failure.getColumnNumber());
		assertEquals(message + RDFParseException.getLocationString(71, column), failure.getMessage());
	}

	private static void assertScansMatchScalar(byte[] bytes, int start, int end) {
		int line = end;
		int quote = end;
		int nonAscii = end;
		int iri = end;
		for (int i = start; i < end; i++) {
			if (line == end && (bytes[i] == '\r' || bytes[i] == '\n')) {
				line = i;
			}
			if (quote == end && (bytes[i] == '"' || bytes[i] == '\\')) {
				quote = i;
			}
			if (nonAscii == end && bytes[i] < 0) {
				nonAscii = i;
			}
			if (iri == end && (bytes[i] == '>' || bytes[i] == '\\')) {
				iri = i;
			}
		}
		assertEquals(line, FastByteScan.findLineBreak(bytes, start, end));
		assertEquals(quote, FastByteScan.findQuoteOrBackslash(bytes, start, end));
		assertEquals(nonAscii, FastByteScan.skipAscii(bytes, start, end));
		assertEquals(Math.min(quote, nonAscii), FastByteScan.findLiteralSpecial(bytes, start, end));
		assertEquals(iri, FastByteScan.findIriSpecial(bytes, start, end));
	}
}
